css:
#tongsci2-2-2-3-2-cover .frame { flex-direction: row; gap: 72px; }
#tongsci2-2-2-3-2-cover .col-text { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 28px; }
#tongsci2-2-2-3-2-cover h1 { font-size: 112px; }
#tongsci2-2-2-3-2-cover .hero-pen { font-size: 56px; transform: rotate(-1.2deg); transform-origin: left center; margin-top: -6px; }
#tongsci2-2-2-3-2-cover .footer { left: 1100px; right: 300px; }
#tongsci2-2-2-3-2-cover .lesson-chip {
  align-self: flex-start; display: inline-flex; gap: 14px; align-items: baseline;
  border: 2px solid var(--ink); border-radius: 999px; padding: 6px 22px; font-size: 26px; font-weight: 600;
}
#tongsci2-2-2-3-2-cover .lesson-chip span { font-family: var(--f-mono); font-size: 22px; color: var(--ink-2); font-weight: 500; }
#tongsci2-2-2-3-2-cover .goals { display: flex; flex-direction: column; gap: 18px; max-width: 980px; }
#tongsci2-2-2-3-2-cover .goals-label { font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--ink-2); }
#tongsci2-2-2-3-2-cover .goal { display: grid; grid-template-columns: 52px 1fr; gap: 6px; font-size: 30px; line-height: 1.42; }
#tongsci2-2-2-3-2-cover .goal .no { font-family: var(--f-display); font-weight: 700; color: var(--ink-2); }
#tongsci2-2-2-3-2-cover .today {
  margin-top: 6px; padding: 20px 28px; background: var(--paper-2); border: 2px solid var(--ink);
  border-radius: 6px; box-shadow: 6px 6px 0 var(--ink); font-size: 32px; line-height: 1.45;
}
#tongsci2-2-2-3-2-cover .today .tag { display: block; font-size: var(--t-small); letter-spacing: .14em; font-weight: 700; color: var(--accent); margin-bottom: 6px; }
#tongsci2-2-2-3-2-cover .col-fig { flex: 0 0 700px; display: flex; flex-direction: column; gap: 14px; padding-top: 24px; }
#tongsci2-2-2-3-2-cover .fig-caption .cap { font-size: 21px; line-height: 1.4; }
#tongsci2-2-2-3-2-cover .share-card { padding: 60px 30px 26px; display: flex; flex-direction: column; gap: 18px; }
#tongsci2-2-2-3-2-cover .share-card h3 { margin: 0; font: 700 34px/1.3 var(--f-display); color: var(--ink); text-wrap: balance; }

js:
/* tongsci2.2-2-3.2.cover */
(function () {
  'use strict';
  const { part } = window.Deck;
  const NS = 'http://www.w3.org/2000/svg';
  const single = (btns) => btns.forEach((b) => b.addEventListener('click', () => {
    const on = b.getAttribute('aria-pressed') !== 'true';
    btns.forEach((x) => x.setAttribute('aria-pressed', String(on && x === b)));
  }));
  const J = (...p) => window.RxT.join(...p);
  const dock = (root, cfg) => window.UDock.mount(root, cfg);
  const stopKeys = (i) => i.addEventListener('keydown', (e) => e.stopPropagation());   // ←→로 장이 넘어가지 않게

  // 1. 표지: 켜 둔 시간을 늘리면 열화상 속 세 기구가 달아오른다
  part('tongsci2-2-2-3-2-cover', (root) => {
    const input = root.querySelector('#hu-time'), lab = root.querySelector('.hu-min');
    const blobs = [...root.querySelectorAll('.hu-b')];
    const draw = () => {
      const t = Number(input.value), f = Math.min(1, t / 40);
      lab.textContent = `${t}분`;
      blobs.forEach((b) => { b.style.opacity = String(t ? Number(b.dataset.o) * (0.12 + 0.88 * f) : 0); b.style.transform = `scale(${0.5 + 0.5 * f})`; });
    };
    input.addEventListener('input', draw); stopKeys(input);
    single([...root.querySelectorAll('.share-opts button')]);
    const answer = (on) => root.querySelector('#pr-waste').classList.toggle('answer', on);
    draw();
    return {
      fragment(f, on) { if (f.dataset.anim === 'hu') answer(on); },
      sync(slide) { const f = slide.querySelector('[data-anim="hu"]'); answer(!!f && f.classList.contains('visible')); },
    };
  });
})();
